import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const dbDir = path.resolve(here, '..', '..', 'db');

const header = `-- ===========================================================================
-- FareFair - complete PostgreSQL schema for pgAdmin
-- ===========================================================================
-- Generated from db/001_schema.sql by "npm run db:sql".
-- Do not edit this file by hand; edit 001_schema.sql and regenerate.
--
-- Target: PostgreSQL 15+
--
-- How to use in pgAdmin 4
--   1. Connect to your database and open Query Tool (Tools > Query Tool).
--   2. Open this file (File > Open...) and press F5 to execute.
--   3. Refresh the object tree: Schemas > farefair > Tables / Views.
--   4. Optional ERD: right-click the database and choose "ERD for Database",
--      or open Tools > ERD Tool and add the farefair tables.
--
-- WARNING
--   The next two statements drop and recreate ONLY the farefair schema.
--   Nothing in public or any other schema is touched.
--
-- Result
--   22 tables, 6 views, 3 functions, 5 triggers, and all foreign keys needed
--   for pgAdmin's ERD tool to draw the complete diagram.
-- ===========================================================================

DROP SCHEMA IF EXISTS farefair CASCADE;
CREATE SCHEMA farefair;

SET search_path TO farefair, public;

`;

const footer = `-- ===========================================================================
-- Self-check: fail loudly if any ERD entity is missing
-- ===========================================================================
DO $verify$
DECLARE
  expected_tables TEXT[] := ARRAY[
    'admin_sessions',
    'admin_users',
    'audit_events',
    'city_corridor_points',
    'city_demo_routes',
    'city_provenance',
    'cities',
    'discount_programs',
    'fare_anomalies',
    'fare_matrix_entries',
    'fare_matrix_versions',
    'fare_policy_versions',
    'fare_quotes',
    'ml_model_versions',
    'ml_models',
    'ml_predictions',
    'ml_training_samples',
    'ordinance_vehicle_applicability',
    'ordinances',
    'trip_points',
    'trips',
    'vehicle_types'
  ];
  expected_views TEXT[] := ARRAY[
    'v_active_fare_matrix',
    'v_city_catalog',
    'v_fare_compliance',
    'v_model_leaderboard',
    'v_ordinance_catalog',
    'v_trip_enriched'
  ];
  missing TEXT[];
BEGIN
  SELECT array_agg(x.name ORDER BY x.name) INTO missing
  FROM unnest(expected_tables) AS x(name)
  WHERE NOT EXISTS (
    SELECT 1
    FROM information_schema.tables t
    WHERE t.table_schema = 'farefair'
      AND t.table_name = x.name
      AND t.table_type = 'BASE TABLE'
  );

  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'FareFair schema is missing tables: %',
      array_to_string(missing, ', ');
  END IF;

  SELECT array_agg(x.name ORDER BY x.name) INTO missing
  FROM unnest(expected_views) AS x(name)
  WHERE NOT EXISTS (
    SELECT 1
    FROM information_schema.views v
    WHERE v.table_schema = 'farefair'
      AND v.table_name = x.name
  );

  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'FareFair schema is missing views: %',
      array_to_string(missing, ', ');
  END IF;

  RAISE NOTICE 'FareFair schema ready: % tables and % views created in schema farefair.',
    array_length(expected_tables, 1),
    array_length(expected_views, 1);
END
$verify$;

-- ===========================================================================
-- ERD inventory: tables and their outgoing foreign keys
-- ===========================================================================
SELECT
  t.table_name,
  (
    SELECT COUNT(*)::int
    FROM information_schema.table_constraints tc
    WHERE tc.table_schema = t.table_schema
      AND tc.table_name = t.table_name
      AND tc.constraint_type = 'FOREIGN KEY'
  ) AS foreign_keys
FROM information_schema.tables t
WHERE t.table_schema = 'farefair'
  AND t.table_type = 'BASE TABLE'
ORDER BY t.table_name;
`;

const schema = await readFile(path.join(dbDir, '001_schema.sql'), 'utf8');
const output = `${header}${schema.trimEnd()}\n\n${footer}`;

await writeFile(path.join(dbDir, 'farefair_pgadmin.sql'), output, 'utf8');
console.log(`[farefair] wrote ${path.join('db', 'farefair_pgadmin.sql')}`);
